import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'orrery-mechanism';
  root.userData.handlers = {};

  const cleanup = {
    geometries: [],
    materials: [],
    textures: [],
    timelines: [],
  };

  // Load primary gear mesh
  const gearGlb = ctx.glbLoader.load(config.assets.meshUrl);
  const primaryGear = gearGlb.scene.children[0].clone();

  // Apply machined-metal PBR properties to gear materials
  const applyGearMaterial = (obj) => {
    obj.traverse((node) => {
      if (node.isMesh && node.material) {
        node.material.roughness = 0.5;
        node.material.metalness = 0.55;
        node.material.clearcoat = 0.2;
        node.material.clearcoatRoughness = 0.3;
        if (node.material.anisotropy !== undefined) {
          node.material.anisotropy = 0.7;
        }
      }
    });
  };

  applyGearMaterial(primaryGear);
  primaryGear.scale.set(1.6, 1.6, 1.6);
  primaryGear.position.set(0, 0, 0);
  root.add(primaryGear);

  // Secondary gear instance (meshed with primary)
  const secondaryGear = primaryGear.clone();
  applyGearMaterial(secondaryGear);
  secondaryGear.scale.set(0.9, 0.9, 0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);
  root.add(secondaryGear);

  // Jewel pivot sphere at primary hub
  const jewelGeom = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#ff2a38'),
    transmission: 0.6,
    ior: 1.76,
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.8,
  });
  const jewel = new THREE.Mesh(jewelGeom, jewelMat);
  root.add(jewel);
  cleanup.geometries.push(jewelGeom);
  cleanup.materials.push(jewelMat);

  // Arbor shafts through both hubs
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshStandardMaterial({ color: new THREE.Color('#16161d') });

  const primaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  primaryShaft.position.set(0, 0, 0);
  root.add(primaryShaft);

  const secondaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  secondaryShaft.position.set(1.15, 0.35, -0.1);
  root.add(secondaryShaft);

  cleanup.geometries.push(shaftGeom);
  cleanup.materials.push(shaftMat);

  // Backdrop plane with base color
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({ color: new THREE.Color('#16161d') });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -3;
  root.add(backdrop);
  cleanup.geometries.push(backdropGeom);
  cleanup.materials.push(backdropMat);

  // Fog for depth atmosphere
  root.fog = new THREE.Fog(0x0b0b10, 5, 11);

  // Contact shadow
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.2, 0.01);
  root.add(shadow);
  cleanup.geometries.push(shadowGeom);
  cleanup.materials.push(shadowMat);

  // Text rendering via font atlas
  const renderText = (content, options) => {
    if (!ctx.fontAtlas) return null;
    if (typeof ctx.fontAtlas.createMesh === 'function') {
      return ctx.fontAtlas.createMesh(content, options);
    } else if (typeof ctx.fontAtlas === 'function') {
      return ctx.fontAtlas(content, options);
    }
    return null;
  };

  // Headline: "The going train"
  const headlineMesh = renderText('The going train', {
    font: 'Lora',
    size: 68,
    weight: 600,
    letterSpacing: -0.005,
  });
  if (headlineMesh) {
    headlineMesh.position.set(0, -1.7, 0.1);
    root.add(headlineMesh);
  }

  // Caption: "34 COMPONENTS / HAND-FINISHED"
  const captionMesh = renderText('34 COMPONENTS / HAND-FINISHED', {
    font: 'JetBrains Mono',
    size: 18,
    weight: 400,
    letterSpacing: 0.08,
  });
  if (captionMesh) {
    captionMesh.position.set(0, -2.1, 0.1);
    root.add(captionMesh);
  }

  // Gear rotation animations (phase-locked meshing)
  const primaryAngularVelocity = 0.08; // rad/s
  const secondaryAngularVelocity = 0.142; // rad/s (negative rotation)

  const primaryRotationDuration = (Math.PI * 2) / primaryAngularVelocity;
  const secondaryRotationDuration = (Math.PI * 2) / secondaryAngularVelocity;

  const rotationTL = gsap.timeline({ repeat: -1 });
  rotationTL.to(primaryGear.rotation, {
    z: Math.PI * 2,
    duration: primaryRotationDuration,
    ease: 'none',
  }, 0);
  rotationTL.to(secondaryGear.rotation, {
    z: -Math.PI * 2,
    duration: secondaryRotationDuration,
    ease: 'none',
  }, 0);
  cleanup.timelines.push(rotationTL);

  // Apply orbit cinematic primitive (camera drift)
  if (ctx.primitives && typeof ctx.primitives.orbit === 'function') {
    ctx.primitives.orbit(root, {
      speed: 0.08,
      radius: 0.2,
    });
  }

  // Resource cleanup
  root.userData.cleanup = () => {
    cleanup.geometries.forEach(g => g.dispose());
    cleanup.materials.forEach(m => m.dispose());
    cleanup.textures.forEach(t => t.dispose());
    cleanup.timelines.forEach(tl => tl.kill());
    gsap.killTweensOf([primaryGear.rotation, secondaryGear.rotation]);
  };

  return root;
}
